"""Saved VAL outputs only. Additive report/correction; frozen K/L code stays unchanged."""
import sys,json,math
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];sys.path.insert(0,str(ROOT))
import pandas as pd
from src.week12.protocol import sha,digest,immutable,Store,load
from src.week12_attribution.analysis import mean_ci
from src.week12_attribution.protocol import study_identity

def main():
 p=ROOT/'results/week12/attribution/v1';a=p/'analysis';status=json.loads((p/'status.json').read_text())
 if not status.get('complete') or status.get('synthetic'):raise ValueError('Completed real K required')
 f=json.loads((a/'QUANTITATIVE_RESULTS_FREEZE.json').read_text())
 for name,h in f['tables'].items():
  if sha(a/(name+'.csv'))!=h:raise ValueError('Original L table checksum changed: '+name)
 ident=study_identity(load());prepared=Store(p/'prepared',ident).rows();perturbations=Store(p/'perturbations',ident).rows();cells=[json.loads(x.read_text()) for x in (p/'completed_cells').glob('*.json') if x.name!='identity.json']
 if any(r['identity']!=digest(ident) or len(r['unit_importance'])!=r['n_units'] or sorted(r['causal_order'])!=list(range(r['n_units'])) for r in cells):raise ValueError('Incompatible completion receipt')
 expected_receipts={digest([r['example']['dataset'],r['example']['query_id'],r['method'],r['budget']])+'.json' for r in prepared}
 if {x.name for x in (p/'completed_cells').glob('*.json') if x.name!='identity.json'}!=expected_receipts:raise ValueError('Completion membership changed')
 if len(prepared)!=600 or len(cells)!=600:raise ValueError('K completeness differs')
 c=pd.read_csv(a/'sufficiency_comprehensiveness.csv');corrected=[]
 for key,g in c.groupby(['dataset','budget','method','m']):
  valid=g[g.retention.notna() & g.retention.map(lambda x:math.isfinite(x) if pd.notna(x) else False)]
  corrected.append(dict(dataset=key[0],budget=key[1],method=key[2],top_m=key[3],eligible_queries=len(valid),available_queries=len(g),**mean_ci(valid.to_dict('records'),'retention',10000,42)))
 R=pd.DataFrame(corrected);R.to_csv(a/'finite_retention_summary.csv',index=False)
 audit=dict(complete_cells=len(cells),prepared_cells=len(prepared),perturbation_rows=len(perturbations),LOO_units=sum(r['action'].startswith('LOO:') for r in perturbations),physical_lm_calls=sum(r['physical_lm_calls'] for r in perturbations),conceptual_lm_calls=len(perturbations),conceptual_prompt_tokens=sum(r['prompt_tokens'] for r in perturbations),conceptual_generated_tokens=sum(r['generated_tokens'] for r in perturbations),K_and_L_code_unchanged=True,original_L_tables_verified=True,finite_retention_note='Original mean_ci accepts NaN after DataFrame coercion; additive finite-only summary excludes undefined ratios. No inference/result changed.',original_quantitative_freeze_sha=sha(a/'QUANTITATIVE_RESULTS_FREEZE.json'),finite_retention_sha=sha(a/'finite_retention_summary.csv'))
 immutable(a/'CLOSEOUT_AUDIT.json',audit)
 U=pd.read_csv(a/'unit_summary.csv');Q=pd.read_csv(a/'query_profiles.csv');S=pd.read_csv(a/'system_quality.csv');C=pd.read_csv(a/'relevance_utility.csv');H=pd.read_csv(a/'paired_harmful_effects.csv');G=pd.read_csv(a/'gold_overlap.csv');T=pd.read_csv(a/'curve_summary.csv')
 def table(df):return df.to_markdown(index=False,floatfmt='.5f')
 summary=[]
 for (d,b),g in S.groupby(['dataset','budget']):
  x=g[g.method=='QBGF_FULL'].iloc[0];y=g[g.method!='QBGF_FULL'].iloc[0];summary.append(dict(dataset=d,budget=b,comparator=y.method,QBGF=x.quality,comparator_quality=y.quality,delta=x.quality-y.quality))
 W=Q[Q.method=='QBGF_FULL'].groupby(['dataset','budget','qbgf_outcome']).size().unstack(fill_value=0).reset_index()
 units=Q.groupby(['dataset','budget','method'],as_index=False).agg(mean_units=('units','mean'),mean_evidence_tokens=('evidence_tokens','mean'))
 lines=['# Week12 K/L — completed evidence-attribution diagnostic','','## Main finding','','Semantic relevance is an imperfect proxy for downstream input-ablation utility. Most individual deletions leave the task score unchanged, yet both helpful and harmful units occur. This does **not** establish that the reader ignored those units. QBGF does not show a consistent diagnostic advantage over the preselected VAL comparator; nothing here changes the Part-I frozen method.','','K is complete. The initially saved L notebook output was **synthetic smoke**, not the real analysis. The real L analysis was subsequently run against completed K shards, without any new model generation. All tables and figures below use real **VAL-only** results. No confirmation outcome was inspected.','','## K: what was executed','','- 150 frozen validation queries: 50 each from HotpotQA, QASPER and SciFact.', '- Two budgets (256/1024), QBGF_FULL plus one comparator selected by full-VAL task quality for each dataset/budget: **600 cells**.', '- Frozen Qwen BASE_FP16 reader/parser; source-exact selected sentence/proposition units or whole selected passages. Only exposed evidence changed.', '- Leave-one-unit-out (LOO), individual-unit sufficiency, and retrospective causal top-1/2/4 ONLY and REMOVE actions.', '- Causal ties use source order/stable ID, not semantic relevance. Full and NONE references reuse prior compatible answers.', '',f"Completed **{audit['perturbation_rows']:,} logical perturbations**, including **{audit['LOO_units']:,} LOO units**, with **{audit['physical_lm_calls']:,} recorded physical LM calls** after reuse. Conceptual prompt tokens: **{audit['conceptual_prompt_tokens']:,}**; generated tokens: **{audit['conceptual_generated_tokens']:,}**. These logical totals include reuse; they are not new physical token-use totals.", '', 'Generation-shard modification times span roughly **2.47 hours**. This describes this run, not a controlled throughput or end-to-end benchmark. All 600 completion cells and original quantitative-table checksums were verified.','','## Original quality on the diagnostic subset','',table(pd.DataFrame(summary)),'','HotpotQA/QASPER use answer F1; SciFact uses aggregate three-class macro-F1. These 50-query VAL subsets are neither fresh confirmation nor the full C/D population. QBGF has higher point estimates in two of six cells. No paired quality-superiority test is inferred from this table. `BM25_PLAIN_RAG` is the historical internal alias for **budget-matched BM25 RAW_SKIP passage RAG**, not unrestricted RAG.','', 'Per-query QBGF wins/losses/ties:', '',table(W),'', 'SciFact win/loss profiles and LOO importance use per-claim correctness; they are not per-query macro-F1 contributions.','','## LOO utility and unit granularity','','Importance = original task score − score after deleting the unit. Positive means deletion hurt; negative means deletion helped; zero means no observed task-score change. Epsilon is zero in this diagnostic.','',table(U[['dataset','budget','method','n_queries','n_units','mean_importance','helpful','neutral','harmful','mean_query_harmful','exact_answer_flip']]),'', 'Across the 9,607 units: **687 helpful (7.15%), 8,311 neutral (86.51%), 609 harmful (6.34%)**. These are pooled unit *counts*, not a pooled task-quality metric; unit sizes/types and cell weights differ. Median importance is zero in every cell.','',table(units),'', 'A sentence and a whole passage are different interventions. For example, SciFact @1024 QBGF averages 27.70 units/query versus 3.12 for BM25 passage RAG. Raw helpful/harmful unit fractions cannot establish which representation is intrinsically superior.','','## Relevance versus utility','','Spearman correlations below use 10,000 frozen paper/query/document-cluster bootstrap resamples, seed 42. They are exploratory nominal 95% intervals, not a newly multiplicity-corrected confirmation family.','',table(C[['dataset','budget','method','rho','ci_low','ci_high','n_units','n_clusters']]),'', 'Ten of twelve intervals include zero. The two positive nominal intervals are HotpotQA passage-only @1024 (rho 0.2212) and SciFact QBGF @256 (rho 0.1344). This supports weak/context-dependent alignment, not the claim that retrieval relevance is useless or that cosine identifies causal evidence. Cross-unit correlations also mix query and granularity effects; within-query correlations are undefined for many constant-importance queries.','',table(U[['dataset','budget','method','top1','top1_tie_aware','top3','top_relevance_negative','top_relevance_zero','within_query_rho','within_query_valid']]),'', 'Tie-aware top-1 agreement is much higher than strict agreement because many units tie at zero. It must not be presented as strong causal-ranking accuracy.','','## Does QBGF expose more harmful evidence?','','Paired query-weighted difference: QBGF harmful-unit fraction minus its comparator.','',table(H[['dataset','budget','mean','ci_low','ci_high','n']]),'', 'Five of six intervals cross zero. SciFact @1024 is nominally negative (−0.0330 [−0.0699, −0.0034]), yet QBGF quality is lower (0.5881 versus 0.7121 macro-F1). Lower per-unit harm therefore does not imply better aggregate answers; redundancy, smaller units and weak beneficial evidence remain plausible explanations. This is not a causal mediation result.','','## Retrospective sufficiency / comprehensiveness','','Top-m units are chosen using observed LOO outcomes from these same queries. These curves are retrospective diagnostics, not deployable selection or independent evidence of a trained policy. Negative sufficiency loss means the chosen subset scored higher than the original context.','',table(T[T.measure=='sufficiency_loss'][['dataset','budget','method','top_m','mean','ci_low','ci_high','n']]),'', 'Top-2/top-4 subsets often recover or exceed full-context point estimates, but many intervals are broad and this selection uses oracle information. SciFact C2 top-2 improves correctness by 0.14 on this subset (nominal interval for full-minus-subset: −0.26 to −0.02); do not report this as a macro-F1 gain or deployable improvement.','', 'Curve eligibility differs: SciFact BM25 @1024 top-4 is available for only **18/50** queries; C2 @256 top-4 for **44/50**. Compare matched eligibility rather than treating every curve as the same cohort. Full comprehensiveness and original curve values are retained in `attribution/v1/analysis/curve_summary.csv`.','','### Retention reporting correction','','The original L table propagates undefined retention ratios (pandas NaN) into its means and counts them as eligible. Undefined ratios occur when original score − NONE score is nonpositive. Original tables and their freeze remain unchanged. `finite_retention_summary.csv` supplies an additive correction using only finite, defined ratios, with 10,000 cluster resamples and explicit eligible counts. This changes reporting only; no answers, source selections or attribution actions were recomputed. Retention can exceed one or be negative and is unstable near a small positive denominator.','',table(R),'','## Gold evidence overlap','','Overlap is retrospective evaluation only, never an inference feature or selection criterion.','',table(G),'', 'Gold-overlapping units generally show higher average deletion impact, but annotations are incomplete. Missing overlap labels were excluded, not treated as negative. In QASPER @256, only 389/467 FIXED_SENTENCE units and 427/511 QBGF units have defined overlap; SciFact also has many undefined units. Non-overlap does not establish false or irrelevant evidence.','','## Figures','','These figures are the original real L outputs. Plot labels retain internal aliases; BM25_PLAIN_RAG means budget-matched RAW_SKIP. SciFact sufficiency plots use mean per-query correctness rather than aggregate macro-F1.']
 for d in ['HotpotQA','QASPER','SciFact']:
  for view in ['unit_categories','relevance_utility','sufficiency']:
   lines+=['',f'![{d} {view}](attribution/v1/analysis/figures/{d}_{view}.png)']
 lines+=['','## Limitations and next step','','- This is post-hoc analysis on already-used VAL, with 50 queries per dataset and full-VAL comparator selection. It is not an unbiased new quality comparison.', '- A zero deletion effect can reflect redundancy, interactions or insensitivity of the answer metric. It does not establish evidence non-use.', '- Importance is context-dependent and non-additive; input ablation does not explain internal reasoning or establish factual causality.', '- Unit length/granularity differences and numerous exploratory intervals limit universal comparisons.', '- Qualitative candidates are automatically selected for inspection and remain labelled MANUAL_REVIEW_REQUIRED; no unsupported case narrative is added.', '- No dynamic controller, new method, retriever change, training, confirmation or QASPER TEST was run.', '', '**Next:** retain the Part-I FIXED_SENTENCE policy exactly as frozen. Part M is implemented and remains explicitly locked pending manual execution. K/L can explain validation behavior; they cannot change confirmation systems, IDs, budgets or hypotheses.','']
 (ROOT/'results/week12/W12_K_L_ATTRIBUTION_REPORT.md').write_text('\n'.join(lines));print(json.dumps(audit,indent=2))
if __name__=='__main__':main()
